size_t usb_xhci_thunderbolt_db_size(void) {
    return sizeof(g_db) / sizeof(g_db[0]);
}

void usb_xhci_thunderbolt_init(void) {
    g_ready = true;
    kprintf("[DRV/xHCI-USB4] USB 3.2 / USB4 xHCI Ring-Buffer TRB Controller + Thunderbolt 4 + 8000Hz HID (%lu rules)\n", (unsigned long)usb_xhci_thunderbolt_db_size());
}

bool usb_xhci_thunderbolt_selftest(void) {
    return g_ready && usb_xhci_thunderbolt_db_size() >= 3520;
}
